import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Task Management System - CLI registration/login + per-user task CRUD.
 *
 * Build:  javac -d bin *.java
 * Run:    java -cp bin Main
 *
 * Commands / prompts (input read from stdin, line by line):
 *   Welcome menu:  "1" Register, "2" Login, "3" Exit
 *   Register:      prompts "Username:", "Password:", "Confirm password:".
 *                  Rejects empty values and duplicate usernames, re-prompting
 *                  until valid. On success prints "Registration successful."
 *                  and appends "username:password" to data/users.txt.
 *   Login:         prompts "Username:" and "Password:". On mismatch prints
 *                  "Error: wrong password. Invalid credentials." and offers
 *                  "Retry login? (y/n):". On success prints "Login successful."
 *   Main menu:     "1" View Tasks, "2" Add Task, "3" Mark Task Completed,
 *                  "4" Delete Task, "5" Logout, "6" Exit.
 *                  - Add Task prompts "Title:" then "Description:".
 *                  - Mark/Delete prompt "Task ID ...:" and print
 *                    "Task <ID> marked Completed" / "Task <ID> deleted".
 *                  Exiting prints "Goodbye".
 *
 * Credentials persist in data/users.txt (created on registration, reloaded on
 * every launch). Tasks persist per user in data/<username>_tasks.txt so a user
 * only ever sees and modifies their own tasks.
 *
 * Task file format (one task per line, fields separated by '|'):
 *   id|title|description|createdTimestamp|status
 *   e.g.  1|Buy milk|2 litres|2026-10-10T12:00:00.000|Pending
 * ID generation: the next ID is (highest existing ID in that user's file) + 1,
 * so IDs are unique and stable per user across restarts. Any '|' typed into a
 * title/description is replaced with '/' to keep the format unambiguous.
 *
 * End of input (stdin closed) is treated as a clean exit, never a crash.
 */
public class Main {

    private static final Path DATA_DIR = Paths.get("data");
    private static final Path USERS_FILE = DATA_DIR.resolve("users.txt");
    private static final String DELIM = "|";
    private static final BufferedReader IN =
            new BufferedReader(new InputStreamReader(System.in));

    public static void main(String[] args) {
        Map<String, String> users = loadUsers();
        try {
            while (true) {
                printWelcome();
                String choice = read("Choice: ");
                if (choice == null) {
                    break;
                }
                if (choice.equals("1")) {
                    register(users);
                } else if (choice.equals("2")) {
                    String user = login(users);
                    if (user != null) {
                        mainMenu(user);
                    }
                } else if (choice.equals("3")) {
                    break;
                } else {
                    System.out.println("Invalid choice.");
                }
            }
        } catch (IOException e) {
            System.out.println("Input error; exiting.");
        }
        System.out.println("Goodbye");
    }

    private static String read(String prompt) throws IOException {
        System.out.print(prompt);
        String line = IN.readLine();
        return line == null ? null : line.trim();
    }

    private static void printWelcome() {
        System.out.println("=== Welcome ===");
        System.out.println("1. Register");
        System.out.println("2. Login");
        System.out.println("3. Exit");
    }

    private static void register(Map<String, String> users) throws IOException {
        while (true) {
            String username = read("Username: ");
            if (username == null) {
                return;
            }
            if (username.isEmpty()) {
                System.out.println("Username cannot be empty.");
                continue;
            }
            if (users.containsKey(username)) {
                System.out.println("Username already exists. Choose another.");
                continue;
            }
            String password = [secret redacted]
            if (password =[secret redacted]
                return;
            }
            if (password.isEmpty()) {
                System.out.println("Password cannot be empty.");
                continue;
            }
            String confirm = read("Confirm password: ");
            if (confirm == null) {
                return;
            }
            if (!password.equals(confirm)) {
                System.out.println("Passwords do not match. Try again.");
                continue;
            }
            users.put(username, password);
            appendUser(username, password);
            System.out.println("Registration successful.");
            return;
        }
    }

    private static String login(Map<String, String> users) throws IOException {
        while (true) {
            String username = read("Username: ");
            if (username == null) {
                return null;
            }
            String password = [secret redacted]
            if (password =[secret redacted]
                return null;
            }
            if (users.containsKey(username) && users.get(username).equals(password)) {
                System.out.println("Login successful.");
                return username;
            }
            System.out.println("Error: wrong password. Invalid credentials.");
            String again = read("Retry login? (y/n): ");
            if (again == null || !again.equalsIgnoreCase("y")) {
                return null;
            }
        }
    }

    private static void mainMenu(String user) throws IOException {
        while (true) {
            System.out.println("=== Main Menu ===");
            System.out.println("1. View Tasks");
            System.out.println("2. Add Task");
            System.out.println("3. Mark Task Completed");
            System.out.println("4. Delete Task");
            System.out.println("5. Logout");
            System.out.println("6. Exit");
            String choice = read("Choice: ");
            if (choice == null) {
                return;
            }
            if (choice.equals("1")) {
                listTasks(user);
            } else if (choice.equals("2")) {
                addTask(user);
            } else if (choice.equals("3")) {
                completeTask(user);
            } else if (choice.equals("4")) {
                deleteTask(user);
            } else if (choice.equals("5")) {
                System.out.println("Logged out.");
                return;
            } else if (choice.equals("6")) {
                System.out.println("Goodbye");
                System.exit(0);
            } else {
                System.out.println("Invalid choice.");
            }
        }
    }

    private static void listTasks(String user) {
        List<Task> tasks = loadTasks(user);
        if (tasks.isEmpty()) {
            System.out.println("No tasks available.");
            return;
        }
        System.out.println("=== Tasks for " + user + " ===");
        for (Task t : tasks) {
            System.out.println("ID: " + t.id
                    + " | Title: " + t.title
                    + " | Description: " + t.description
                    + " | Created: " + t.timestamp
                    + " | Status: " + t.status);
        }
    }

    private static void addTask(String user) throws IOException {
        String title;
        while (true) {
            title = read("Title: ");
            if (title == null) {
                return;
            }
            if (!title.isEmpty()) {
                break;
            }
            System.out.println("Title cannot be empty.");
        }
        String description = read("Description: ");
        if (description == null) {
            return;
        }
        List<Task> tasks = loadTasks(user);
        Task t = new Task();
        t.id = nextId(tasks);
        t.title = sanitize(title);
        t.description = sanitize(description);
        t.timestamp = LocalDateTime.now().toString();
        t.status = "Pending";
        tasks.add(t);
        saveTasks(user, tasks);
        System.out.println("Task " + t.id + " added.");
    }

    private static void completeTask(String user) throws IOException {
        List<Task> tasks = loadTasks(user);
        Integer id = readTaskId("Task ID to mark completed: ");
        if (id == null) {
            return;
        }
        for (Task t : tasks) {
            if (t.id == id) {
                t.status = "Completed";
                saveTasks(user, tasks);
                System.out.println("Task " + id + " marked Completed");
                return;
            }
        }
        System.out.println("Task " + id + " not found.");
    }

    private static void deleteTask(String user) throws IOException {
        List<Task> tasks = loadTasks(user);
        Integer id = readTaskId("Task ID to delete: ");
        if (id == null) {
            return;
        }
        for (int i = 0; i < tasks.size(); i++) {
            if (tasks.get(i).id == id) {
                tasks.remove(i);
                saveTasks(user, tasks);
                System.out.println("Task " + id + " deleted");
                return;
            }
        }
        System.out.println("Task " + id + " not found.");
    }

    private static Integer readTaskId(String prompt) throws IOException {
        while (true) {
            String s = read(prompt);
            if (s == null) {
                return null;
            }
            try {
                return Integer.parseInt(s);
            } catch (NumberFormatException e) {
                System.out.println("Please enter a numeric task ID.");
            }
        }
    }

    private static int nextId(List<Task> tasks) {
        int max = 0;
        for (Task t : tasks) {
            if (t.id > max) {
                max = t.id;
            }
        }
        return max + 1;
    }

    private static String sanitize(String s) {
        return s.replace(DELIM, "/").replace("\n", " ").replace("\r", " ");
    }

    private static Path tasksFile(String user) {
        return DATA_DIR.resolve(user + "_tasks.txt");
    }

    private static List<Task> loadTasks(String user) {
        List<Task> tasks = new ArrayList<>();
        Path file = tasksFile(user);
        if (!Files.exists(file)) {
            return tasks;
        }
        try {
            for (String line : Files.readAllLines(file)) {
                if (line.isEmpty()) {
                    continue;
                }
                String[] p = line.split("\\" + DELIM, -1);
                if (p.length < 5) {
                    continue;
                }
                Task t = new Task();
                try {
                    t.id = Integer.parseInt(p[0]);
                } catch (NumberFormatException e) {
                    continue;
                }
                t.title = p[1];
                t.description = p[2];
                t.timestamp = p[3];
                t.status = p[4];
                tasks.add(t);
            }
        } catch (IOException e) {
            System.out.println("Could not read " + file + ": " + e.getMessage());
        }
        return tasks;
    }

    private static void saveTasks(String user, List<Task> tasks) throws IOException {
        Files.createDirectories(DATA_DIR);
        StringBuilder sb = new StringBuilder();
        for (Task t : tasks) {
            sb.append(t.id).append(DELIM)
              .append(t.title).append(DELIM)
              .append(t.description).append(DELIM)
              .append(t.timestamp).append(DELIM)
              .append(t.status).append(System.lineSeparator());
        }
        Files.write(tasksFile(user), sb.toString().getBytes(),
                StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
    }

    private static Map<String, String> loadUsers() {
        Map<String, String> users = new LinkedHashMap<>();
        if (!Files.exists(USERS_FILE)) {
            return users;
        }
        try {
            for (String line : Files.readAllLines(USERS_FILE)) {
                int sep = line.indexOf(':');
                if (sep > 0) {
                    users.put(line.substring(0, sep), line.substring(sep + 1));
                }
            }
        } catch (IOException e) {
            System.out.println("Could not read " + USERS_FILE + ": " + e.getMessage());
        }
        return users;
    }

    private static void appendUser(String username, String password) throws IOException {
        Files.createDirectories(DATA_DIR);
        Files.write(USERS_FILE,
                (username + ":" + password + System.lineSeparator()).getBytes(),
                StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    private static class Task {
        int id;
        String title;
        String description;
        String timestamp;
        String status;
    }
}

