private static void filterTasks(String user, String expr) {
    int eq = expr.indexOf('=');
    if (eq <= 0) {
        System.out.println("Usage: /filter priority=<High|Medium|Low> or /filter tag=<tag>");
        return;
    }
    String key = [secret redacted]
    String value = expr.substring(eq + 1).trim();
    List<Task> matches = new ArrayList<>();
    for (Task t : loadTasks(user)) {
        if (key.equals("priority") && t.priority.equalsIgnoreCase(value)) {
            matches.add(t);
        } else if (key.equals("tag") && hasTag(t, value)) {
            matches.add(t);
        }
    }
    if (matches.isEmpty()) {
        System.out.println("No tasks match " + expr + ".");
        return;
    }
    printTasks(user, matches);
}

private static void sortTasks(String user, String key) {
    List<Task> tasks = loadTasks(user);
    if (key.equalsIgnoreCase("deadline")) {
        tasks.sort((a, b) -> deadlineKey(a).compareTo(deadlineKey(b)));
    } else if (key.equalsIgnoreCase("priority")) {
        tasks.sort((a, b) -> priorityRank(a.priority) - priorityRank(b.priority));
    } else {
        System.out.println("Usage: /sort deadline or /sort priority");
        return;
    }
    if (tasks.isEmpty()) {
        System.out.println("No tasks available.");
        return;
    }
    printTasks(user, tasks);
}

private static boolean hasTag(Task t, String tag) {
    for (String s : t.tags.split(",")) {
        if (s.trim().equalsIgnoreCase(tag)) {
            return true;
        }
    }
    return false;
}

private static String deadlineKey(Task t) {
    return t.deadline.isEmpty() ? "9999-12-31" : t.deadline;
}

private static int priorityRank(String p) {
    if (p.equalsIgnoreCase("High")) {
        return 0;
    }
    if (p.equalsIgnoreCase("Medium")) {
        return 1;
    }
    return 2;
}

