private static String normalizePriority(String p) {
    if (p.equalsIgnoreCase("High")) {
        return "High";
    }
    if (p.equalsIgnoreCase("Low")) {
        return "Low";
    }
    if (p.equalsIgnoreCase("Medium")) {
        return "Medium";
    }
    System.out.println("Unknown priority '" + p + "'; defaulting to Medium.");
    return "Medium";
}

