// Full-text search: case-insensitive substring match across title AND
// description; includes archived tasks so hidden items remain findable.
private static void searchTasks(String user, String query) {
    if (query.isEmpty()) {
        System.out.println("Usage: /search <text>");
        return;
    }
    String needle = query.toLowerCase();
    List<Task> matches = new ArrayList<>();
    for (Task t : loadTasks(user)) {
        if (t.title.toLowerCase().contains(needle)
                || t.description.toLowerCase().contains(needle)) {
            matches.add(t);
        }
    }
    if (matches.isEmpty()) {
        System.out.println("No tasks match '" + query + "'.");
        return;
    }
    printTasks(user, matches);
}

// Archive/unarchive: toggles the persisted archive flag.
private static void setArchived(String user, String idText, boolean archived) throws IOException {
    Integer id = parseId(idText);
    if (id == null) {
        return;
    }
    List<Task> tasks = loadTasks(user);
    for (Task t : tasks) {
        if (t.id == id) {
            t.archived = archived;
            saveTasks(user, tasks);
            if (archived) {
                System.out.println("Task " + id + " archived, hiding from main list");
            } else {
                System.out.println("Task " + id + " unarchived; now visible");
            }
            return;
        }
    }
    System.out.println("Task " + id + " not found.");
}

