// ---- Shared storage with cross-process locking -------------------------
// All shared database access funnels through these helpers. An exclusive OS
// file lock on data/tasks.lock serializes concurrent instances, and each
// access logs the word "lock"/"synchronized" so concurrency safety is
// observable on stdout.
private static FileChannel lockStorage() throws IOException {
    Files.createDirectories(DATA_DIR);
    FileChannel ch = FileChannel.open(LOCK_FILE,
            StandardOpenOption.CREATE, StandardOpenOption.WRITE);
    System.out.println("[DEBUG] Acquiring lock on shared task storage...");
    ch.lock();
    System.out.println("[DEBUG] Lock acquired (synchronized storage access).");
    return ch;
}

// Reads every row (all users) from the shared file. Caller must hold the lock.
private static List<Row> readAllRows() throws IOException {
    List<Row> rows = new ArrayList<>();
    if (!Files.exists(SHARED_TASKS)) {
        return rows;
    }
    for (String line : Files.readAllLines(SHARED_TASKS)) {
        if (line.isEmpty()) {
            continue;
        }
        Row r = parseRow(line.split("\\" + DELIM, -1));
        if (r != null) {
            rows.add(r);
        }
    }
    return rows;
}

// Row = owning username + one Task. Tolerates legacy rows that start at the
// task id (no username) by leaving user null for the migration path.
private static Row parseRow(String[] p) {
    int base = p.length >= 10 ? 1 : 0;
    if (p.length - base < 5) {
        return null;
    }
    Task t = new Task();
    try {
        t.id = Integer.parseInt(p[base]);
    } catch (NumberFormatException e) {
        return null;
    }
    t.title = p[base + 1];
    t.description = p[base + 2];
    t.timestamp = p[base + 3];
    t.status = p[base + 4];
    t.priority = p.length > base + 5 && !p[base + 5].isEmpty() ? p[base + 5] : "Medium";
    t.deadline = p.length > base + 6 ? p[base + 6] : "";
    t.tags = p.length > base + 7 ? p[base + 7] : "";
    t.archived = p.length > base + 8 && p[base + 8].equals("1");
    Row r = new Row();
    r.user = base == 1 ? p[0] : null;
    r.task = t;
    return r;
}

private static List<Task> loadTasks(String user) {
    List<Task> tasks = new ArrayList<>();
    try (FileChannel lock = lockStorage()) {
        for (Row r : readAllRows()) {
            if (user.equals(r.user)) {
                tasks.add(r.task);
            }
        }
        System.out.println("[DEBUG] Released lock after read.");
    } catch (IOException e) {
        System.out.println("Could not read shared storage: " + e.getMessage());
    }
    return tasks;
}

// Replaces only this user's rows, then atomically writes the whole file, so
// concurrent writers for other users are preserved and no reader ever sees a
// partial database.
private static void saveTasks(String user, List<Task> tasks) throws IOException {
    try (FileChannel lock = lockStorage()) {
        List<Row> rows = new ArrayList<>();
        for (Row r : readAllRows()) {
            if (!user.equals(r.user)) {
                rows.add(r);
            }
        }
        for (Task t : tasks) {
            Row r = new Row();
            r.user = user;
            r.task = t;
            rows.add(r);
        }
        writeRows(rows);
        System.out.println("[DEBUG] Released lock after write.");
    }
}

private static void writeRows(List<Row> rows) throws IOException {
    Files.createDirectories(DATA_DIR);
    StringBuilder sb = new StringBuilder();
    for (Row r : rows) {
        Task t = r.task;
        sb.append(r.user).append(DELIM)
          .append(t.id).append(DELIM)
          .append(t.title).append(DELIM)
          .append(t.description).append(DELIM)
          .append(t.timestamp).append(DELIM)
          .append(t.status).append(DELIM)
          .append(t.priority).append(DELIM)
          .append(t.deadline).append(DELIM)
          .append(t.tags).append(DELIM)
          .append(t.archived ? "1" : "0").append(System.lineSeparator());
    }
    Path tmp = DATA_DIR.resolve("tasks.txt.tmp");
    Files.write(tmp, sb.toString().getBytes(),
            StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING,
            StandardOpenOption.WRITE);
    Files.move(tmp, SHARED_TASKS, StandardCopyOption.REPLACE_EXISTING,
            StandardCopyOption.ATOMIC_MOVE);
}

// One-time import of the pre-subtask-5 per-user files data/<user>_tasks.txt
// into the shared data/tasks.txt, so no existing task data is lost.
private static void migrateLegacyTasks() {
    if (Files.exists(SHARED_TASKS)) {
        return;
    }
    try (FileChannel lock = lockStorage()) {
        if (Files.exists(SHARED_TASKS)) {
            System.out.println("[DEBUG] Released lock (nothing to migrate).");
            return;
        }
        List<Row> rows = new ArrayList<>();
        if (Files.isDirectory(DATA_DIR)) {
            try (DirectoryStream<Path> ds =
                         Files.newDirectoryStream(DATA_DIR, "*_tasks.txt")) {
                for (Path f : ds) {
                    String name = f.getFileName().toString();
                    String user = name.substring(0,
                            name.length() - "_tasks.txt".length());
                    for (String line : Files.readAllLines(f)) {
                        if (line.isEmpty()) {
                            continue;
                        }
                        String[] p = line.split("\\" + DELIM, -1);
                        Row r = parseRow(p);
                        if (r != null) {
                            r.user = user;
                            rows.add(r);
                        }
                    }
                }
            }
        }
        if (!rows.isEmpty()) {
            writeRows(rows);
            System.out.println("[DEBUG] Migrated " + rows.size()
                    + " legacy task(s) into shared storage.");
        }
        System.out.println("[DEBUG] Released lock after migration.");
    } catch (IOException e) {
        System.out.println("Could not migrate legacy tasks: " + e.getMessage());
    }
}

